pub fn genericPathWithPrettyInitialized(path: Fs.Path, target: options.Target, top_level_dir: []const u8, allocator: std.mem.Allocator) !Fs.Path {
        const buf = bun.path_buffer_pool.get();
        defer {
        _ = bun.path_buffer_pool.put(buf);
        }
        const is_node = bun.strings.eqlComptime(path.namespace, "node");
        if ((is_node and (bun.strings.hasPrefixComptime(path.text, NodeFallbackModules.import_path) or (!std.fs.path.isAbsolute(path.text))))) {
            return path;
        }
        if ((path.isFile() or is_node)) {
            const buf2 = (if ((target == .bake_server_components_ssr)) bun.path_buffer_pool.get() else buf);
            defer {
            if ((target == .bake_server_components_ssr)) {
                _ = bun.path_buffer_pool.put(buf2);
            }
            }
            const rel = bun.path.relativePlatformBuf(buf2, top_level_dir, path.text, .loose, false);
            var path_clone = path;
            _ = &path_clone;
            if ((target == .bake_server_components_ssr)) {
                path_clone.pretty = (blk_catch_84: { break :blk_catch_84 ((std.fmt.bufPrint(buf, "ssr:{s}", .{ rel })) catch |__ce_84| { _ = &__ce_84; break :blk_catch_84 buf[0..]; }); });
            } else {
                path_clone.pretty = rel;
            }
            return path_clone.dupeAllocFixPretty(allocator);
        } else {
            var path_clone = path;
            _ = &path_clone;
            const NamespaceAlt = std.fmt.Alt(string, fmtEscapedNamespace);
            _ = &NamespaceAlt;
            path_clone.pretty = (blk_catch_85: { break :blk_catch_85 ((std.fmt.bufPrint(buf, "{s}{f}:{s}", .{ (if ((target == .bake_server_components_ssr)) "ssr:" else ""), NamespaceAlt{ .data = path.namespace }, path.text })) catch |__ce_85| { _ = &__ce_85; break :blk_catch_85 buf[0..]; }); });
            return path_clone.dupeAllocFixPretty(allocator);
        }
}

pub fn fmtEscapedNamespace(slice: []const u8, w: *std.Io.Writer) !void {
        var rest = slice;
        _ = &rest;
        while (bun.strings.indexOfChar(rest, 58)) |i| {
            _ = try w.writeAll(rest[0..i]);
            _ = try w.writeAll("::");
            rest = rest[(i + 1)..];
        }
        _ = try w.writeAll(rest);
}

pub fn cheapPrefixNormalizer(prefix: []const u8, suffix: []const u8) [2][]const u8 {
        if ((prefix.len == 0)) {
            const suffix_no_slash = bun.strings.removeLeadingDotSlash(suffix);
            return .{ (if (strings.hasPrefixComptime(suffix_no_slash, "../")) "" else "./"), suffix_no_slash };
        }
        if ((strings.endsWithChar(prefix, 47) or (Environment.isWindows and strings.endsWithChar(prefix, 92)))) {
            if ((strings.startsWithChar(suffix, 47) or (Environment.isWindows and strings.startsWithChar(suffix, 92)))) {
                return .{ prefix[0..prefix.len], suffix[1..suffix.len] };
            }
        }
        return .{ prefix, bun.strings.removeLeadingDotSlash(suffix) };
}

